package cn.kaoyan.assistant;
import java.io.*;import java.nio.file.*;
public class OfficeCacheTest {static void check(boolean v,String m){if(!v)throw new AssertionError(m);}public static void main(String[] args)throws Exception{check(AttachmentProvider.typeFor("source.doc").equals("application/msword"),"DOC must open with Office MIME");File root=Files.createTempDirectory("office-cache-test").toFile();try{File source=new File(root,"original.docx");Files.write(source.toPath(),new byte[]{1,2,3});File first=OfficePreview.cacheFile(source);check(first.equals(OfficePreview.cacheFile(source)),"same original must reuse cache");Files.write(source.toPath(),new byte[]{1,2,3,4});check(!first.equals(OfficePreview.cacheFile(source)),"changed original must invalidate cache");File cache=OfficePreview.cacheFile(source);Files.write(cache.toPath(),"%PDF-cached".getBytes("UTF-8"));File imported=new File(root,"original.pdf");Files.write(imported.toPath(),"%PDF-original".getBytes("UTF-8"));File partial=new File(root,"office-123.part");Files.write(partial.toPath(),new byte[]{0});check(OfficePreview.clear(root)==2,"cache and partial must be cleared");check(source.isFile()&&imported.isFile(),"clearing cache removed original document");System.out.println("Office cache reuse, invalidation and original-preserving cleanup checked");}finally{for(File f:root.listFiles())f.delete();root.delete();}}}
